useEffect(() => {
  const id = setInterval(() => setSeconds(s => s + 1), 1000);
  return () => clearInterval(id); // cleanup: la unmount / re-run
}, [running]);

// același tipar pentru ORICE abonament (listener, subscribe, conexiune):
useEffect(() => {
  const onClick = () => console.log("click");
  document.body.addEventListener("click", onClick);
  // fără linia aceasta → listeners care se adună la fiecare mount:
  return () => document.body.removeEventListener("click", onClick);
}, []);
