// 1) creezi contextul; \`undefined\` implicit → prinzi folosirea greșită
const ActiveStepContext = createContext(undefined);

// 2) un Provider ține starea și o pune „în aer"
function ActiveStepProvider({ steps, children }) {
  // lazy initializer: citim o singură dată din localStorage
  const [activeId, setActiveId] = useState(() => localStorage.getItem(KEY) ?? steps[0].id);

  // orice schimbare se salvează → la refresh rămâi pe același demo
  useEffect(() => localStorage.setItem(KEY, activeId), [activeId]);

  return (
    <ActiveStepContext.Provider value={{
      activeId,
      setActiveId,
      steps
    }}>
      {children}
    </ActiveStepContext.Provider>
  );
}

// 3) un hook custom îl consumă (aceeași valoare pentru toți)
function useActiveStep() {
  const ctx = useContext(ActiveStepContext);
  if (!ctx) throw new Error("...folosit în afara <ActiveStepProvider>");
  return ctx;
}

// 4) înfășori (wrap) consumatorii — provider-ul TREBUIE să fie DEASUPRA lor (App.tsx)
<ActiveStepProvider steps={demos}>
  <AppShell />
</ActiveStepProvider>

// 5) în orice component dinăuntru, fără props. Header-ul și dropdown-ul de mai sus
//    fac EXACT același apel — de aceea se mișcă amândouă odată:
const { activeId, setActiveId, steps } = useActiveStep();
