// src/app/api/chat/route.ts — apelul la LLM stă pe SERVER, unde e cheia
import { streamText, convertToModelMessages } from "ai";
import { anthropic } from "@ai-sdk/anthropic";
import { DEFAULT_MODEL_ID } from "@/lib/providers";

export const runtime = "nodejs";

export async function POST(request: Request) {
  const { messages } = await request.json();

  // citită ÎN handler, nu la import: altfel \`next build\` cade fără .env.local
  if (!process.env.ANTHROPIC_API_KEY) return Response.json({ error: "Lipsește cheia." }, { status: 400 });

  const result = streamText({
    model: anthropic(DEFAULT_MODEL_ID),              // id-ul modelului vine din REGISTRU
    messages: convertToModelMessages(messages)       // formatul de UI ≠ formatul pentru model
  });

  return result.toUIMessageStreamResponse({
    onError: () => "Providerul nu a răspuns."        // niciodată mesajul brut al SDK-ului în UI
  });
}
