// src/lib/providers.ts — REGISTRUL. Ajunge în browser, deci ZERO chei aici.
export const PROVIDERS: Record<ProviderId, ProviderInfo> = {
  anthropic: { id: "anthropic", label: "Anthropic", available: true, models: [{ id: ANTHROPIC_MODEL, label: "Claude" }] },
  openai: { id: "openai", label: "OpenAI", available: true, models: [{ id: OPENAI_MODEL, label: "GPT" }] }
};

// src/lib/providers.server.ts — DOAR pe server: aici trăiesc cheile
export function getModel(providerId: ProviderId, modelId: string) {
  const known = PROVIDERS[providerId]?.models.some(m => m.id === modelId);
  const model = known ? modelId : DEFAULT_MODEL_ID; // id necunoscut → implicit, nu mai departe
  if (providerId === "openai") return createOpenAI({ apiKey: process.env.OPENAI_API_KEY })(model);
  return createAnthropic({ apiKey: process.env.ANTHROPIC_API_KEY })(model);
}

// clientul nu vede niciodată cheia — doar dacă providerul e configurat
export const isProviderConfigured = (id: ProviderId) => Boolean(process.env[ENV_KEY[id]]);

// UI-ul ITEREAZĂ registrul → un provider nou = o intrare, nu cod nou
PROVIDER_LIST.map(p => <Item key={p.id} disabled={!p.available}>{p.label}</Item>);
