// SELECTOR: componenta se re-randează doar când se schimbă CE a cerut
const providerId = useAppStore(state => state.providerId);

// ⚠️ selectorul NU construiește obiecte noi — referință nouă la fiecare randare
// = re-randare la infinit. Selectori separați, sau comparație superficială.
const { a, b } = useAppStore(state => ({ a: state.a, b: state.b })); // GREȘIT

// sincronizare la FINALUL streamingului, nu per token: \`persist\` scrie sincron
// în localStorage la fiecare set → per token ar serializa tot istoricul de sute de ori
