// src/lib/cost.ts — O SINGURĂ formulă, folosită și per mesaj și pe total
export function costOf(usage: Usage, price: Price) {
  if (usage.inputTokens == null) return null; // „necunoscut" ≠ 0 (un zero pare gratis)
  return (usage.inputTokens * price.input + usage.outputTokens * price.output) / 1_000_000;
}

