// src/lib/tools/update-learning-plan.ts — o unealtă = descriere + schemă + execuție
import { tool } from "ai";
import { z } from "zod";

export const updateLearningPlan = tool({
  // descrierea NU e comentariu: e singurul lucru pe baza căruia modelul decide să cheme unealta
  description: "Actualizează planul de învățare al utilizatorului când apar pași noi de făcut.",
  inputSchema: z.object({
    steps: z.array(z.string()).min(1).describe("Pașii planului, în ordine")
  }),
  execute: async ({ steps }) => savePlan(steps) // rulează pe SERVER, în ruta de chat
});

// în route.ts — modelul poate cere unealta, apoi continuă cu rezultatul ei
const result = streamText({
  model,
  messages: convertToModelMessages(messages),
  tools: { updateLearningPlan, rememberFact },
  stopWhen: stepCountIs(5) // fără el, bucla se oprește după PRIMUL apel de unealtă
});

// pe client, apelul se vede în \`parts\`, nu într-un câmp separat
{
  m.parts.map(p => (p.type === "tool-updateLearningPlan" ? <ToolCard state={p.state} input={p.input} /> : null));
}
